%% smajram_rotation.m
% Generates rotated SMAjram character images from the base character images.
%
% Input:
%   PNG images generated by generate_smajram_characters.m
%
% Output:
%   Rotated PNG images using the configured rotation angles.
%
% The rotation routine is included as a local function in this file.

%% User Configuration

source_folder = 'AjramMain';
destination_folder = 'AjramRotT';
img_type = '.png';

% Maximum rotation angle.
% The default configuration produces:
% -45, -15, 0, 15, 45 degrees.
theta = 45;

% Execution feedback
show_progress = true;    % Show progress in the Command Window
show_visuals = false;    % Display source/result images during processing
progress_interval = 0.01; % Update progress at approximately every 1%

%% Prepare image list

source = dir(fullfile(source_folder, ['*' img_type]));

% Start output global IDs automatically after the number of input images.
% For 72,000 input images, the first rotation output ID is 72001.
output_id_start = numel(source) + 1;

img_list = 1:numel(source);

if isempty(source)
    error('No %s images were found in source folder: %s', ...
        img_type, source_folder);
end

if ~exist(destination_folder, 'dir')
    mkdir(destination_folder);
end

% Construct the rotation-angle list used in the original workflow.
thetay = linspace(-theta, theta, 4);
thetay_mid = round(length(thetay) / 2);
theta_list = [thetay(1:thetay_mid), 0, thetay(thetay_mid+1:end)];

%% Generate rotated images

rotate_smajram_images(source, theta_list, img_type, ...
    destination_folder, img_list, output_id_start, ...
    show_progress, show_visuals, progress_interval);

%% Local function

function new_img = rotate_smajram_images(source, theta_list, img_type, ...
    destination, img_list, output_id_start, ...
    show_progress, show_visuals, progress_interval)

im_folder = source(img_list);
file_path = im_folder(1).folder;
filen = {im_folder.name}';

num_images = numel(img_list);
num_angles = numel(theta_list);
num_op_images = num_images * num_angles;

new_img = strings(num_op_images, 1);
iter = 0;

% Start progress timer
start_time = tic;
next_progress = progress_interval;

if show_progress
    fprintf('\nSMAjram Rotation\n');
    fprintf('Input images: %d\n', num_images);
    fprintf('Rotation angles: %d\n', num_angles);
    fprintf('Expected output images: %d\n\n', num_op_images);
    fprintf('Progress:   0%%');
end

for i = 1:num_images
    img = imread(fullfile(file_path, filen{i}));

    % Extract the source filename components used in the output name.
    [~, source_name, ~] = fileparts(filen{i});

    % Source format:
    % g0000000012(s100){Bahij Janna Bold}_Naon
    %
    % Remove the original global ID and retain everything beginning
    % with the font-size field.
    metadata_start = strfind(source_name, '(s');

    if isempty(metadata_start)
        error('Unexpected source filename format: %s', filen{i});
    end

    metadata = source_name(metadata_start(1):end);

    for j = 1:num_angles
        rotated_img = imrotate(img, theta_list(j), 'bilinear', 'crop');

        iter = iter + 1;
        output_id = output_id_start + iter - 1;

        image_id = sprintf('g%010d', output_id);
        rotation_tag = sprintf('(A%d)', theta_list(j));

        new_img(iter) = strcat( ...
            image_id, rotation_tag, metadata, img_type);

        image_path = fullfile(destination, new_img(iter));

        % Protect existing output files from accidental overwriting.
        if isfile(image_path)
            error('Output file already exists; refusing to overwrite: %s', ...
                image_path);
        end

        imwrite(rotated_img, image_path);

        if show_visuals
            imshowpair(img, rotated_img, 'montage');
            title(sprintf('Rotation: %d degrees', theta_list(j)));
            drawnow;
        end
    end

    % Display processing progress
    if show_progress
        progress = i / num_images;

        if progress >= next_progress || i == num_images
            elapsed_time = toc(start_time);

            fprintf('\b\b\b\b%3.0f%%', progress * 100);

            next_progress = next_progress + progress_interval;
        end
    end
end

if show_progress
    fprintf('\nRotation completed.\n');
    fprintf('Output images: %d\n', num_op_images);
    fprintf('Elapsed time: %.1f seconds.\n\n', elapsed_time);
end

end
